function validate([nums, lower, upper]) {
  if (nums.length > 100) return 'nums holds at most 100 values.';
  if (lower < -1e9 || upper > 1e9 || lower > upper) return 'Need -10^9 <= lower <= upper <= 10^9.';
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] < lower || nums[i] > upper) return 'Every value of nums must lie between lower and upper.';
    if (i > 0 && nums[i] <= nums[i - 1]) return 'nums must be strictly increasing (sorted, no repeats).';
  }
  return null;
}

