function findMissingRanges(nums, lower, upper) {
  const ranges = [];
  let next = lower;

  for (const num of nums) {
    if (num > next) {
      ranges.push([next, num - 1]);
    }
    next = num + 1;
  }
  if (next <= upper) {
    ranges.push([next, upper]);
  }
  return ranges;
}

