function findMissingRanges(nums, lower, upper) {
  // Every missing run starts at lower or just after some value of nums.
  const present = new Set(nums);
  const starts = [lower, ...nums.map(v => v + 1)].filter(s => s <= upper && !present.has(s));
  const result = [];
  for (const start of starts) {
    let end = upper;
    for (const v of nums) if (v > start && v - 1 < end) end = v - 1;
    result.push([start, end]);
  }
  return result.sort((a, b) => a[0] - b[0]);
}

