function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let lower, upper, count;
  if (size === 'large') {
    lower = int(-1e9, 0);
    upper = rand() < 0.5 ? int(0, 1e9) : lower + int(100, 400);
    count = 100;
  } else {
    lower = int(-10, 10);
    upper = lower + int(0, 15);
    count = int(0, Math.min(8, upper - lower + 1));
  }
  const picked = new Set();
  if (rand() < 0.3) picked.add(lower);
  if (rand() < 0.3 && picked.size < count) picked.add(upper);
  while (picked.size < count) {
    const value = rand() < 0.4 && picked.size ? [...picked][int(0, picked.size - 1)] + 1 : int(lower, upper);
    if (value <= upper) picked.add(value);
  }
  const nums = [...picked].sort((a, b) => a - b);
  return [nums, lower, upper];
}
